"""Keyframe images generated by the Codex CLI's built-in image tool (ChatGPT login, no API key needed).

Each image is one `codex exec` run in the output folder: the prompt (sent on stdin, because `-i` takes a list of
files) asks Codex to generate the picture with its image tool and save it under a given name. Reference images
(album cover, character sheet) are attached with `-i`. A shot that continues the previous one also gets the previous
keyframe attached, so it is drawn as the next moment of the same take; such jobs run after the one they continue.
"""

from __future__ import annotations

import subprocess
import threading
import time
from concurrent.futures import ThreadPoolExecutor
from dataclasses import dataclass, field
from pathlib import Path

from PIL import Image

SIZES = {"landscape": "1536x1024", "portrait": "1024x1536"}


@dataclass
class ImageJob:
    out: Path
    prompt: str
    orientation: str  # landscape | portrait
    refs: list[Path] = field(default_factory=list)
    previous: Path | None = None  # keyframe of the shot this one continues (attached once it exists)

    def attachments(self) -> list[Path]:
        return [*self.refs, *([self.previous] if self.previous and self.previous.exists() else [])]


def _instruction(job: ImageJob) -> str:
    refs, files = "", job.attachments()
    if files:
        names = ", ".join(f"attached image {i + 1} ({p.stem.replace('_', ' ')})" for i, p in enumerate(files))
        refs = (f"Reference images: {names}. Match the palette, mood and paper-craft style of the references, and if a "
                "character sheet is attached the woman must look exactly like the woman on it. ")
    if job.previous in files:
        refs += (f"Attached image {len(files)} is the PREVIOUS MOMENT of this same continuous camera take: keep the "
                 "same place, set pieces, lighting, palette, weather and character (same clothes, same hair), built "
                 "from the same paper pieces; change only what the scene below describes (where the camera moved, how "
                 "the action progressed). It must look like a later frame of the same film, not a new illustration. ")
    return (f"Use your image generation tool to create ONE {job.orientation} image ({SIZES[job.orientation]}) and save "
            f"it to ./{job.out.name}. {refs}{job.prompt} No text, no letters, no labels, no watermark, no border. "
            "Do not do anything else and do not modify any other file.")


def generate(job: ImageJob, timeout: float = 900, retries: int = 1) -> float:
    """Run Codex until `job.out` exists as a valid image. Returns seconds spent; skips if the file already exists."""
    if job.out.exists():
        return 0.0
    job.out.parent.mkdir(parents=True, exist_ok=True)
    cmd = ["codex", "exec", "--skip-git-repo-check", "-s", "workspace-write", "-C", str(job.out.parent), "--json"]
    for ref in job.attachments():
        cmd += ["-i", str(ref.resolve())]
    started = time.monotonic()
    last_error = ""
    for _attempt in range(retries + 1):
        log = job.out.with_suffix(".jsonl")
        with log.open("w") as out, job.out.with_suffix(".err").open("w") as err:
            r = subprocess.run(cmd, input=_instruction(job), text=True, stdout=out, stderr=err,
                               timeout=timeout, check=False)
        if job.out.exists():
            try:
                with Image.open(job.out) as im:
                    im.verify()
                return time.monotonic() - started
            except OSError as e:
                last_error = f"invalid image: {e}"
                job.out.unlink()
        else:
            last_error = f"codex exit {r.returncode}, no {job.out.name}"
    raise RuntimeError(f"{job.out.name}: {last_error}")


def chains(jobs: list[ImageJob]) -> list[list[ImageJob]]:
    """Group jobs so a job continuing another job of the batch runs after it, in the same chain."""
    out: list[list[ImageJob]] = []
    chain_of: dict[Path, list[ImageJob]] = {}
    for job in jobs:
        chain = chain_of.get(job.previous) if job.previous else None
        if chain is None:
            chain = []
            out.append(chain)
        chain.append(job)
        chain_of[job.out] = chain
    return out


def generate_all(jobs: list[ImageJob], workers: int = 4, on_done=None, should_stop=None) -> dict[str, float | str]:
    """Generate chains in parallel (each chain in order); returns {file name: seconds or error message}.
    `should_stop()` cancels the images not started yet."""
    results: dict[str, float | str] = {}
    lock = threading.Lock()

    def run(chain: list[ImageJob]) -> None:
        for job in chain:
            if should_stop and should_stop():
                result: float | str = "CANCELLED"
            else:
                try:
                    result = round(generate(job), 1)
                except Exception as e:  # noqa: BLE001 - one failed image must not stop the batch
                    result = f"ERROR {e}"
            with lock:
                results[job.out.name] = result
                if on_done:
                    on_done(job, result)

    with ThreadPoolExecutor(max_workers=workers) as pool:
        for fut in [pool.submit(run, c) for c in sorted(chains(jobs), key=len, reverse=True)]:
            fut.result()
    return results
